"use client";
import { useEffect, useMemo, useRef, useState, useSyncExternalStore, type FormEvent, type ReactNode } from "react";
import { ArrowRight, BookOpen, Check, CheckCheck, ChevronRight, ClipboardCheck, Copy, Download, Eye, FileText, GraduationCap, Heart, KeyRound, Library, MessageCircle, Pencil, Plus, Search, ShieldCheck, Sparkles, Target, Trash2, Trophy, Users, Volume2, X } from "lucide-react";
import { activities, worlds, type Activity } from "@/lib/content";
