  const pendingLearners = filteredStudents.map(student => ({ student, rows: studentRows(student.id), reviewWorld: worlds.find(world => getWorldStatus(progressByStudent.get(student.id)!, world.id).status === "review") })).filter(item => item.reviewWorld).sort((a, b) => (average(a.rows) ?? 0) - (average(b.rows) ?? 0));
  const successful = scopedSubmissions.filter(row => row.score >= 80).length; const activeLearners = new Set(scopedSubmissions.map(row => row.studentId)).size;

  useEffect(() => {
    if (!modal) return; const timer = window.setTimeout(() => dialogRef.current?.querySelector<HTMLElement>("input, select, textarea, button")?.focus(), 20);
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape" && !busy) setModal(null); if (event.key === "Tab") { const elements = [...(dialogRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), a[href]') || [])].filter(element => element.offsetParent !== null); const first = elements[0]; const last = elements[elements.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } };
    document.addEventListener("keydown", onKey); return () => { window.clearTimeout(timer); document.removeEventListener("keydown", onKey); };
  }, [modal, busy]);
  async function execute(action: PlatformAction, success?: string) { setBusy(true); setError(""); try { const result = await onAction(action); if (!result.ok) throw new Error(result.error || "Não foi possível salvar."); if (success) setMessage(success); return result; } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível concluir. Tente novamente."); return null; } finally { setBusy(false); } }
